// CSD_RATIONALE_BEGIN
// Math-word-problem CSD. The strategy generates a step-by-step solution with
// symbolic expressions and the final answer wrapped in << >> delimiters.
//
// State tracked:
//   - generated: full visible output including delimiter tokens
//   - insideConstrainedOut: whether we are inside a << >> span
//   - currentConstrainedOut: tokens accumulated inside the current span
//   - steps/cost: token budget consumed
//
// Decision logic:
//   Outside a span: generate freely with UnconstrainedStep. When "<<" appears,
//   enter constrained mode (either observed or forced after preamble).
//   Inside a span: if the parser accepts the current constrained prefix as
//   complete, close the span with CloseSpanIfComplete. Otherwise, use
//   AdaptiveConstrainedStep with the caller-supplied token groups for soft
//   preference while the parser enforces hard validity. This handles both
//   intermediate symbolic expressions (e.g., "3 + 4 = 7") and the final
//   numeric answer inside << >>.
//
// The task requires visible << >> delimiters, so we use OpenConstrainedSpan /
// EnterObservedConstrainedSpan and CloseConstrainedSpan / CloseSpanIfComplete.
// We append task guidance once at the start to steer the model toward the
// step-by-step + delimited-answer format.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   1. Outside-span branch (next == "<<"):
//      We set currentConstrainedOut := [] which satisfies parser.IsValidPrefix([])
//      by the method precondition. insideConstrainedOut becomes true only then.
//   2. CloseSpanIfComplete branch:
//      When closed == true, insideConstrainedOut becomes false making the
//      implication vacuously true. When closed == false, generated/inside/current
//      are unchanged, so the invariant is preserved trivially.
//   3. AdaptiveConstrainedStep + AppendConstrainedToken branch:
//      AdaptiveConstrainedStep returns either EOS or a parser-valid next token
//      (by its contract). AppendConstrainedToken extends currentConstrainedOut
//      with a parser-valid token, preserving IsValidPrefix by the parser's
//      prefix-extension property.
//
// progress (|generated| <= |generatedPrefix| + steps):
//   Outside-span: steps += 1; generated grows by at most 1 (the non-EOS token
//   appended). So |generated| <= |generatedPrefix| + steps is preserved.
//   CloseSpanIfComplete: steps += 1; CloseSpanIfComplete appends at most ">>"
//   (1 token) to generated, so growth is at most 1 per step.
//   Constrained step: steps += 1; AppendConstrainedToken appends exactly 1
//   token to generated (EOS causes break without appending). Bound preserved.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve the math problem step by step. Wrap each symbolic expression and the final answer inside << >> delimiters. For example: The cost is <<3 * 4 = 12>> dollars, so the answer is <<12>>.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else {
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

cost := steps;

// CSD_RATIONALE_BEGIN
// Math-word-problem CSD with strict final-answer span control.
//
// Key insights from failure analysis:
// 1. The model was generating malformed content inside << >> spans (using {var}
//    template syntax, ** operator, etc.) because constrained generation wasn't
//    being applied effectively.
// 2. The primary failure is "syntax_valid_semantic_mismatch" (26/49) - model
//    produces syntactically valid spans but wrong answers, often because it
//    generates the wrong formula or includes invalid characters.
// 3. Unclosed spans (3/49) occurred when the model hit EOS mid-span.
// 4. The constrained intervention activity was near-zero (7/49 examples), meaning
//    the parser was barely being used.
//
// Strategy:
// - Generate freely with UnconstrainedChunk until "<<" is observed.
// - Once inside a span, use hard constrained generation (ConstrainedStep) to
//   ensure only parser-valid tokens are emitted.
// - After each constrained token, check CloseSpanIfComplete to close as soon
//   as the parser accepts the expression.
// - Use CloseSpanWithinBudget as a safety net if the span budget is running low.
// - For the final answer span, use SafeRepetitionPenaltyStep to avoid repeating
//   content from earlier in the output.
// - Strong task guidance directs the model to emit only numeric expressions
//   inside << >> without template variables like {n} or {var}.
//
// The key fix: instead of letting unconstrained generation produce the span
// content (which allowed malformed expressions), we switch to ConstrainedStep
// inside every span. This ensures parser validity at every token position.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity invariant:
//   1. Outside-span branch (UnconstrainedChunk):
//      When stoppedOnOpenSpan is true, generatedOut already ends with "<<" and
//      we call EnterObservedConstrainedSpan which sets currentConstrainedOut := []
//      (valid by precondition parser.IsValidPrefix([])). When stoppedOnEos or
//      neither delimiter was seen, insideConstrainedOut remains false, making
//      the implication vacuous.
//   2. CloseSpanIfComplete branch (inside span):
//      When closed == true, insideConstrainedOut becomes false (implication
//      vacuously true, currentConstrainedOut cleared to []). When closed == false,
//      generated/inside/current are unchanged and the invariant is trivially
//      preserved.
//   3. ConstrainedStep + AppendConstrainedToken branch:
//      ConstrainedStep returns either EOS or a token t such that
//      parser.IsValidPrefix(currentConstrainedOut + [t]) holds (by ConstrainedStep
//      contract). AppendConstrainedToken sets currentConstrainedOut :=
//      currentConstrainedOut + [t], which is parser-valid. EOS causes break
//      without any state mutation.
//   4. CloseSpanWithinBudget branch (safety net):
//      By its postcondition: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//      This directly satisfies the invariant.
//
// progress invariant (|generated| <= |generatedPrefix| + steps):
//   Outside-span (UnconstrainedChunk): stepsUsed is the actual budget consumed,
//   and generatedOut grows by at most stepsUsed tokens (EOS and open-span
//   delimiter are counted but visible growth is bounded by stepsUsed). We add
//   stepsUsed to steps.
//   CloseSpanIfComplete: costs +1 step, appends at most ">>" (1 token). Preserved.
//   ConstrainedStep + AppendConstrainedToken: costs +1 step, appends exactly 1
//   token (or 0 on EOS break). Preserved.
//   CloseSpanWithinBudget: costs at most closeBudget steps, appends at most
//   closeBudget tokens. We add closeBudget to steps, bounding |generated|.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve step by step. For EACH intermediate calculation and the final numeric answer, write exactly one expression inside << >>. Inside << >> use ONLY numbers and operators + - * / // % ( ) int. NO variables like {n}, NO ** operator, NO curly braces. Final answer must be a single number expression like <<42>> or <<3*4+2>>.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    // Generate freely until we see "<<" or EOS
    var chunkBudget := maxSteps - steps;
    if chunkBudget > 40 {
      chunkBudget := 40;
    }
    var generatedOut, stoppedOnOpenSpan, stoppedOnEos, stepsUsed :=
      helpers.UnconstrainedChunk(lm, prompt, generated, chunkBudget, "<<", eosToken);
    steps := steps + stepsUsed;
    generated := generatedOut;
    if stoppedOnEos {
      break;
    }
    if stoppedOnOpenSpan {
      // "<<" is already in generatedOut; enter constrained mode without adding another delimiter
      var g2, i2, c2 := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := g2;
      insideConstrainedOut := i2;
      currentConstrainedOut := c2;
    }
  } else {
    // Inside a constrained span
    // First check if we can close cleanly
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
    } else {
      // If budget is very low, use CloseSpanWithinBudget as safety net
      var remainingBudget := maxSteps - steps;
      if remainingBudget <= 5 && remainingBudget > 0 {
        var sg, si, sc := helpers.CloseSpanWithinBudget(
          lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainingBudget
        );
        generated := sg;
        insideConstrainedOut := si;
        currentConstrainedOut := sc;
        steps := steps + remainingBudget;
      } else {
        // Use hard constrained step to ensure only parser-valid tokens
        var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
        var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
        if next == eosToken {
          // Safety: try to close the span before breaking
          if maxSteps - steps > 0 {
            var sg2, si2, sc2 := helpers.CloseSpanWithinBudget(
              lm, parser, prompt, generated, currentConstrainedOut, eosToken, 1
            );
            generated := sg2;
            insideConstrainedOut := si2;
            currentConstrainedOut := sc2;
            steps := steps + 1;
          }
          break;
        } else {
          var ag, ai, ac := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, next
          );
          generated := ag;
          insideConstrainedOut := ai;
          currentConstrainedOut := ac;
        }
      }
    }
  }
}

cost := steps;
